import{z as s,x as p,o as i,c as A,q as l,j as r,D as E,d as t,s as o,S as B,b as e}from"./chunks/framework.C8m1ZpeB.js";const x=JSON.parse('{"title":"逆向选择对非执行风险","description":"","frontmatter":{"title":"逆向选择对非执行风险","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/adverse-selection-vs-nonexecution.md","filePath":"quant/adverse-selection-vs-nonexecution.md","lastUpdated":1791063341000}'),d={name:"quant/adverse-selection-vs-nonexecution.md"};function m(u,a,c,h,f,D){const n=p("Mermaid");return i(),A("div",null,[a[2]||(a[2]=l('<h1 id="逆向选择对非执行风险" tabindex="-1">逆向选择对非执行风险 <a class="header-anchor" href="#逆向选择对非执行风险" aria-label="Permalink to &quot;逆向选择对非执行风险&quot;">​</a></h1><div class="epigraph"><p>限价单有两种死法：成交在对你不利的时候（被捡），或到截止仍不成交（非执行）。最优挂单是在这两份风险之间分配，而不是单独最小化其中一份。</p><footer>—— 据 Foucault 对 picking-off 与等待的讨论；对照 Copeland and Galai, Information Effects on the Bid-Ask Spread, Journal of Finance, 1983</footer></div><p><a href="/quant/limit-vs-market-choice">限价对市价</a>给出何时离开队列去吃。缺口是：一旦选择限价，失败有两种经济学完全相反的方式。逆向选择（成交条件于坏消息）要求你挂得更保守、或更勤撤单；非执行（\\(\\pi_{\\mathrm{fill}}\\) 太低）要求你挂得更有攻击性。两者对价格的含义相反。本课把权衡写清，为下一课最优放置提供目标函数，不重推 Foucault 均衡存在。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>被捡是条件于成交的损失：\\(E[V\\mid\\)成交\\(]\\) 比挂单价更差。非执行是条件于不成交的损失：你仍要在更差的价格完成，或根本完不成对冲。只防被捡，会把单子埋到远处，几乎永不成交，截止时被迫吃更宽的价差——非执行成本爆掉。只防非执行，会贴在 BBO 甚至越过，变成几乎市价，再加被捡。问题是同一决策变量（挂单价、展示、撤单频率）如何同时进入两份期望损失。</p><p><span class="marginnote">可以想象成路边摆摊卖货：标价太高，一天无人问津，收摊前只能贱卖（非执行）；标价太低，最先买走的恰恰是那些知道真实行情更贵的人（被捡）。最优标价不是把哪种风险压到零，而是让两份期望损失之和最小。</span></p><p>Easley–O&#39;Hara 的事件不确定放大被捡：有事件时成交更可能到来。Parlour 的队深放大非执行：队尾 \\(\\pi_{\\mathrm{fill}}\\) 低。状态要把两者同时包括。</p><h3 id="成交是坏消息-不成交也是消息" tabindex="-1">成交是坏消息，不成交也是消息 <a class="header-anchor" href="#成交是坏消息-不成交也是消息" aria-label="Permalink to &quot;成交是坏消息，不成交也是消息&quot;">​</a></h3><p>限价卖出成交，暗示有人愿意在此刻买，可能是好消息（对卖方不利）。限价卖出一直不成交，可能是没有买家，也可能价值正在下跌、市价单去打买方。不成交更新事件后验，与「无交易是无事件」同族。把非执行当成外生概率噪声，会丢掉学习。</p><p><span class="marginnote">执行算法文献把非执行叫做 implementation risk，把被捡叫做 adverse selection 或 toxicity。本课保持微观结构用语，不引入新的经纪商标签。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>限价卖在价格 \\(p\\) 的期望效用可写成</p> \\[\\pi(p)\\,E[p-V\\mid \\text{fill at }p] + (1-\\pi(p))\\,U_{\\mathrm{nx}}(p), \\]<p>其中 \\(\\pi\\) 随 \\(p\\) 更有攻击性而升（非执行降），条件期望 \\(E[V\\mid\\mathrm{fill}]\\) 同时变差（逆向选择升）。一阶条件：放松 \\(p\\) 带来的成交概率收益，等于边际被捡恶化。波动 \\(\\sigma\\) 主要进入条件期望；队深 \\(n\\) 主要进入 \\(\\pi\\)；截止 \\(T\\) 进入 \\(U_{\\mathrm{nx}}\\)。</p><p><span class="marginnote">代入数字看权衡：\\(\\pi=0.5\\)、被捡后的成交收益 0.98、非执行效用 0.95，期望效用 \\(=0.5\\times0.98+0.5\\times0.95=0.965\\)；把单子挂得更激进使 \\(\\pi=0.8\\)，但成交收益跌到 0.96，期望 \\(=0.8\\times0.96+0.2\\times0.95=0.958\\)，反而更差。最优挂单价就是让这个加权和取到峰值的点。</span></p><p>经验分离：成交后中点向对手方向永久移动，是被捡/信息；限价撤单后自己改市价且中点未走，是非执行。Hasbrouck 永久影响对「限价成交」子样本应高于「随机时刻」，若限价成交被选中为信息事件。</p><h3 id="两种风险的日内节奏" tabindex="-1">两种风险的日内节奏 <a class="header-anchor" href="#两种风险的日内节奏" aria-label="Permalink to &quot;两种风险的日内节奏&quot;">​</a></h3><p>开盘事件不确定高，被捡权重大，挂单应更保守或更短寿命。收盘截止硬，非执行权重大，同一人改贴 BBO 或改市价。这与策略噪声的收盘聚集一致，不必假设下午知情者变多。公告窗口两者同时升：\\(\\pi\\) 可能升（活动密）但 \\(E[V\\mid\\mathrm{fill}]\\) 更毒，净效应是价差宽、限价寿命短。</p>',18)),(i(),r(B,null,{default:E(()=>[o(n,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20LR%0A%20%20P%5B%22%E6%8C%82%E5%8D%95%E4%BB%B7%20p%22%5D%20--%3E%20Pi%5B%22%CF%80fill%20%E9%9D%9E%E6%89%A7%E8%A1%8C%22%5D%0A%20%20P%20--%3E%20AS%5B%22E%5BV%7Cfill%5D%20%E9%80%86%E5%90%91%E9%80%89%E6%8B%A9%22%5D%0A%20%20Pi%20--%3E%20Obj%5B%22%E6%9C%9F%E6%9C%9B%E6%95%88%E7%94%A8%22%5D%0A%20%20AS%20--%3E%20Obj%0A%20%20Nx%5B%22%E6%88%AA%E6%AD%A2%E6%97%B6%20U_nx%22%5D%20--%3E%20Obj%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"流动性供给的「公平价差」必须同时买这两份保险。只按 Glosten-Milgrom 补偿逆向选择，会低估那些必须成交的挂单者所要求的攻击性溢价；只按库存补偿等待，会低估被捡。HFT 做市把撤单速度当作第三工具：降低限价寿命，同时压被捡与（若补得够快）非执行。速度竞赛单元会说明第三工具的社会成本。",-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"初学者容易以为限价单「免费」提供流动性、永远优于市价；实际上限价的两种失败都在收费——被捡是成交瞬间的显性损失，非执行是截止时被迫吃更宽价差的隐性损失。哪种更贵取决于波动、队深与截止硬度，没有普适答案。")],-1)),(i(),r(B,null,{default:E(()=>[o(n,{id:"mermaid-60",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E5%8F%AA%E9%98%B2%E4%B8%80%E7%A7%8D%E5%A4%B1%E8%B4%A5%E4%BC%9A%E6%80%8E%E6%A0%B7%22%5D%20--%3E%20A%5B%22%E5%8F%AA%E9%98%B2%E8%A2%AB%E6%8D%A1%20%E5%8D%95%E5%AD%90%E6%8C%82%E5%88%B0%E8%BF%9C%E5%A4%84%22%5D%0A%20%20Q%20--%3E%20B%5B%22%E5%8F%AA%E9%98%B2%E9%9D%9E%E6%89%A7%E8%A1%8C%20%E8%B4%B4%E4%BD%8FBBO%E8%BF%91%E4%B9%8E%E5%B8%82%E4%BB%B7%22%5D%0A%20%20A%20--%3E%20C%5B%22%E5%87%A0%E4%B9%8E%E4%B8%8D%E6%88%90%E4%BA%A4%20%E6%88%AA%E6%AD%A2%E6%97%B6%E8%A2%AB%E8%BF%AB%E5%90%83%E5%AE%BD%E4%BB%B7%E5%B7%AE%22%5D%0A%20%20B%20--%3E%20D%5B%22%E8%A2%AB%E6%8D%A1%E6%A6%82%E7%8E%87%E5%9B%9E%E5%88%B0%E5%B8%82%E4%BB%B7%E6%B0%B4%E5%B9%B3%22%5D%0A%20%20C%20--%3E%20E%5B%22%E4%B8%A4%E7%A7%8D%E5%A4%B1%E8%B4%A5%E7%9A%84%E7%BB%8F%E6%B5%8E%E5%AD%A6%E7%9B%B8%E5%8F%8D%20%E5%BF%85%E9%A1%BB%E4%B8%80%E8%B5%B7%E5%AE%9A%E4%BB%B7%22%5D%0A%20%20D%20--%3E%20E%0A%20%20E%20--%3E%20F%5B%22%E5%85%AC%E5%B9%B3%E4%BB%B7%E5%B7%AE%E5%90%8C%E6%97%B6%E8%A1%A5%E5%81%BF%E4%B8%A4%E4%BB%BD%E4%BF%9D%E9%99%A9%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=l('<p>这张图回答的问题是：把两种失败拆开各防一种为什么会双双失败——两条极端路线在相反的方向上各爆一份成本。</p><p>对效率：被捡主导时，成交更有信息，VR 的短正自相关来自信息写入；非执行主导时，更多是队列摩擦，价格暂时成分来自补给。度量时要把限价成交与市价成交分开算永久影响。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>公式是部分均衡：\\(\\pi(p)\\) 依赖别人的策略。结构估计要回到 Goettler–Parlour–Rajan 一类计算均衡。隐藏单分别改变可见 \\(\\pi\\) 与真实被捡，下一课之后再拆。多市场时本地不成交不等于全局非执行，智能路由改写 \\(U_{\\mathrm{nx}}\\)。</p><p><span class="marginnote">实现价差为负，常常是被捡项赢了；限价完成率低，常常是非执行项赢了。两个 KPI 一起看，才知道阈值往哪边偏。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>限价失败有被捡与非执行两种；对挂单价的比较静态相反。</li><li>最优是边际成交概率收益等于边际逆向选择恶化，再加截止惩罚。</li><li>开盘偏防被捡，收盘偏防非执行；公告窗口两者同时恶化。</li><li>出处：Copeland and Galai, <em>Journal of Finance</em>, 1983；Foucault, <em>Journal of Financial Markets</em>, 1999；动态权衡见 Roşu, 2009。</li></ul>',7))])}const b=s(d,[["render",m]]);export{x as __pageData,b as default};
